edits.new:
.lead { transition: color 0.4s; }
li::marker { color: rgb(1, 2, 3); }
input::placeholder { letter-spacing: 2px; }
input[type=file]::file-selector-button { outline-offset: 7px; }
dialog::backdrop { opacity: 0.5; }
.pseudo::after { outline-offset: 7px; }

.lead { transition: color 0.4s; tab-size: 4; }
ul.list { tab-size: 4; }
ul.list > li:first-child { tab-size: 2; }

#link { text-decoration-thickness: 1px; }
.lead, .pseudo, h1, .wide, .scheme, ul.list > li, pre, footer.site { cursor: pointer; }
ul.list { padding-block: 4px; }
